from __future__ import annotations
from itertools import product
from typing import Sequence, TypeVar
T = TypeVar("T")

def distance(x: Sequence[T], y: Sequence[T]) -> int:
    if len(x) != len(y): raise ValueError("length mismatch")
    return sum(a != b for a, b in zip(x, y))

if __name__ == "__main__":
    books = list(product(range(2), repeat=3))
    matrix = [[distance(x, y) for y in books] for x in books]
    print(*(" ".join(map(str, row)) for row in matrix), sep="\n")
    assert min(matrix[i][j] for i in range(8) for j in range(8) if i != j) == 1

from __future__ import annotations
from itertools import product
from math import comb

def distance(x: tuple[int, ...], y: tuple[int, ...]) -> int:
    return sum(a != b for a, b in zip(x, y))

def ball_size(A: int, L: int, r: int) -> int:
    return sum(comb(L, j) * (A-1) ** j for j in range(min(L, r)+1))

if __name__ == "__main__":
    A, L, r = 3, 5, 2
    center = (0,) * L
    observed = sum(distance(center, b) <= r for b in product(range(A), repeat=L))
    expected = ball_size(A, L, r)
    print(f"formula={expected}, enumeration={observed}")
    assert observed == expected

