from __future__ import annotations

def decoder_bound(A: int, L: int, N: int) -> tuple[int, int, float]:
    if min(A, L, N) < 0: raise ValueError("nonnegative inputs required")
    total = pow(A, L)
    unnamed = max(0, total-N)
    return total, unnamed, unnamed/total if total else 0.0

from __future__ import annotations
from typing import Sequence, TypeVar
T = TypeVar("T")

def distance_matrix(books: Sequence[Sequence[T]]) -> list[list[int]]:
    n = len(books); matrix = [[0]*n for _ in range(n)]
    for i in range(n):
        for j in range(i+1, n):
            if len(books[i]) != len(books[j]): raise ValueError("length mismatch")
            d = sum(x != y for x, y in zip(books[i], books[j]))
            matrix[i][j] = matrix[j][i] = d
    return matrix

from __future__ import annotations
from math import comb

def hamming_ball_size(A: int, L: int, r: int) -> int:
    if A < 1 or L < 0 or r < 0: raise ValueError("invalid parameters")
    return sum(comb(L,j) * (A-1)**j for j in range(min(r,L)+1))

