from __future__ import annotations
from itertools import product

def make_svg(path: str = "cube.svg") -> None:
    books=list(product((0,1), repeat=3)); pos={b:(90+180*b[0]+65*b[2],80+150*b[1]+45*b[2]) for b in books}
    edges=[]
    for i,a in enumerate(books):
        for b in books[i+1:]:
            if sum(x!=y for x,y in zip(a,b))==1:
                x1,y1=pos[a]; x2,y2=pos[b]; edges.append(f"<line x1='{x1}' y1='{y1}' x2='{x2}' y2='{y2}' stroke='#64748b' stroke-width='2'/>")
    nodes=[f"<circle cx='{pos[b][0]}' cy='{pos[b][1]}' r='20' fill='#14b8a6'/><text x='{pos[b][0]}' y='{pos[b][1]+5}' text-anchor='middle' font-family='monospace'>{''.join(map(str,b))}</text>" for b in books]
    svg="<svg xmlns='http://www.w3.org/2000/svg' width='430' height='330'><rect width='100%' height='100%' fill='#f8fafc'/><text x='215' y='28' text-anchor='middle' font-family='sans-serif' font-size='18'>Length-three binary Hamming cube</text>"+''.join(edges+nodes)+"</svg>"
    open(path,'w',encoding='utf-8').write(svg)

if __name__ == '__main__': make_svg()

from __future__ import annotations
from math import comb

def make_svg(A: int = 3, L: int = 10, path: str = "shells.svg") -> None:
    values=[comb(L,j)*(A-1)**j for j in range(L+1)]; peak=max(values); bars=[]
    for j,v in enumerate(values):
        h=220*v/peak; x=45+j*42
        bars.append(f"<rect x='{x}' y='{270-h:.1f}' width='30' height='{h:.1f}' fill='#2563eb'/><text x='{x+15}' y='292' text-anchor='middle' font-family='sans-serif' font-size='11'>{j}</text>")
    svg=f"<svg xmlns='http://www.w3.org/2000/svg' width='540' height='320'><rect width='100%' height='100%' fill='#fff'/><text x='270' y='25' text-anchor='middle' font-family='sans-serif' font-size='18'>Hamming shells: A={A}, L={L}</text>{''.join(bars)}<line x1='40' y1='270' x2='515' y2='270' stroke='#222'/></svg>"
    open(path,'w',encoding='utf-8').write(svg)

if __name__ == '__main__': make_svg()

